class Solution {
public:
    int islandPerimeter(vector<vector<int>>& grid) {

        int total = 0;
        int colcommon = 0;
        int rowcommon = 0;

        for(int i = 0; i < grid.size(); i++){

            for(int j = 0; j < grid[0].size(); j++){

                if(grid[i][j] == 1)
                    total++;

            }

        }

        if(total == 1)
            return 4;

        for(int i = 0; i < grid.size(); i++){

            for(int j = 0; j < grid[0].size() - 1; j++){

                if(grid[i][j] == 0)
                    continue;

                if(grid[i][j] == grid[i][j + 1])
                    rowcommon += 2;

            }

        }

        for(int j = 0; j < grid[0].size(); j++){

            for(int i = 0; i < grid.size() - 1; i++){

                if(grid[i][j] == 0)
                    continue;

                if(grid[i][j] == grid[i + 1][j])
                    colcommon += 2;

            }

        }

        cout << total << endl << rowcommon << endl << colcommon << endl;

        return (4*total) - rowcommon - colcommon;

    }
};

class Solution {
public:
    int islandPerimeter(vector<vector<int>>& grid) {
        int islands = 0, neighbours = 0;
        int r = grid.size();
        if (r == 0) return islands;
        int c = grid[0].size();
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                if (grid[i][j] == 1) {
                    islands++;
                    if (i < r - 1 and grid[i + 1][j] == 1) neighbours++;
                    if (j < c - 1 and grid[i][j + 1] == 1) neighbours++;
                }
            }
        }
        return islands*4 - neighbours*2;
    }
};

class Solution(object):
    def islandPerimeter(self, grid):
        """
        :type grid: List[List[int]]
        :rtype: int
        """
        r, c = len(grid), len(grid[0])
        ans = 0
        dx = [1, -1, 0, 0]
        dy = [0, 0, 1, -1]
        for i in range(r):
            for j in range(c):
                if grid[i][j] == 1:
                    for k in range(4):
                        new_i = i + dx[k]
                        new_j = j + dy[k]
                        if new_i < 0 or new_i >= r or new_j < 0 or new_j >= c or grid[new_i][new_j] == 0:
                            ans += 1
        return ans
